async function downloadStepSheets(layout,which='all',extraFiles=[]){
 if(stepExportBusy){toast('A STEP export is already running.');return;}
 try{
  if(which==='all'&&layout.unplaced.length)throw Error('Place all project parts in Nesting before exporting the complete STEP pack.');const sheets=which==='all'?layout.sheets:layout.sheets.filter(s=>s.number===which);if(!sheets.length)throw Error('Choose a nested sheet first.');const manifests=sheets.map(sheetStepManifest),project=JSON.stringify(serializeProject(state),null,2),fileBase=basename(),files=[];
  stepExportBusy=true;$$('.step-download').forEach(b=>b.disabled=true);toast('Loading solid CAD engine for STEP export… The first export downloads the engine.');
  for(const [i,sheet]of sheets.entries()){const data=await exportSheetStep(sheet,({done,total})=>toast('Building sheet '+sheet.number+' · solid '+done+'/'+total+' · sheet '+(i+1)+'/'+sheets.length));files.push([sheetStepFilename(sheet),data]);}
  if(which!=='all'){download(files[0][1],fileBase+' '+files[0][0],'application/step');toast('Sheet '+sheets[0].number+' STEP downloaded. Create fixed-size stock in CAM; use the STEP information button for setup details.');}
  else{files.push(['START-HERE-CAM.txt',stepSetupGuide(manifests)],['sheet-manifest.json',JSON.stringify({format:'cabinet-nested-step',version:1,units:'mm',sheets:manifests},null,2)],['project.cabinet.json',project]);for(const [name,data]of extraFiles)if(!files.some(f=>f[0]===name))files.push([name,data]);download(zipFiles(files),fileBase+(extraFiles.length?' documents-and-STEP.zip':' nested-STEP.zip'),'application/zip');toast(sheets.length+' STEP sheets downloaded with stock dimensions and CAM setup instructions.');}
 }catch(e){toast('STEP export failed: '+e.message,'error');}finally{stepExportBusy=false;render();}
}
